import express from 'express';
import { isExternalURL } from './utils.js';

const app = express();

app.get('/redirect', (req, res) => {
  const redirectLocation = req.query.url;
  const redirectType = req.query.type || 'push';

  const pendingPush = redirectType !== 'replace';

  if (redirectLocation !== undefined) {
    if (isExternalURL(redirectLocation)) {
      // External redirect logic with bug
      const redirectHref = redirectLocation;
      const redirectError = createRedirectErrorForAction(redirectHref, redirectType);
      res.status(302).redirect(redirectHref);
    } else {
      // Internal redirect logic
      const redirectHref = redirectLocation;
      const redirectError = createRedirectErrorForAction(redirectHref, redirectType);
      res.status(200).send('Internal Redirect');
    }
  } else {
    res.status(400).send('Bad Request');
  }
});

function createRedirectErrorForAction(redirectHref, resolvedRedirectType) {
  const redirectError = new Error(`Redirect to ${redirectHref}`);
  redirectError.handled = true;
  return redirectError;
}

app.listen(3000, () => console.log('Server running on port 3000'));

