// Test cases that fail with the bug
// and pass when fixed
import assert from 'assert';
import http from 'http';

function testRedirect(url, expectedStatusCode, expectedBody, done) {
  http.get(`http://localhost:3000/redirect?url=${encodeURIComponent(url)}`, (res) => {
    const { statusCode } = res;
    let rawData = '';
    res.on('data', (chunk) => { rawData += chunk; });
    res.on('end', () => {
      assert.strictEqual(statusCode, expectedStatusCode);
      assert.strictEqual(rawData, expectedBody);
      done();
    });
  });
}

console.log('Running tests...');

// Test external redirect
testRedirect('http://external.com', 302, '', () => {
  console.log('External redirect test passed');
});

// Test internal redirect
testRedirect('/internal-page', 200, 'Internal Redirect', () => {
  console.log('Internal redirect test passed');
});

